#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto doOp = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int placed=0; placed<n; placed++){
        int pos=-1;
        for(int i=placed;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        if(pos==placed) continue;

        if(placed==0){
            // Move target to position n-1 first if not there
            if(pos!=n-1){
                // op(pos, 1): suffix=[p[n-1]], middle=[pos..n-2], prefix=[0..pos-1]
                // result: [p[n-1]][p[pos]..p[n-2]][p[0]..p[pos-1]]
                // target was at pos, now at pos in new array? No...
                // Just move to end: op with x=pos+1, y=n-1-pos needs x+y=n, invalid
                // Use two steps: swap to n-1 via op(1, n-1-pos) if pos>0
                if(pos>0 && 1+(n-1-pos)<n){
                    doOp(1, n-1-pos); // target at pos goes to end: pos - 0 ... 
                    pos=n-1; // need to verify
                    for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                }
                if(pos!=n-1 && pos+1<n && n-1-pos>0 && (pos+1)+(n-1-pos)<n){ /*impossible*/ }
            }
            if(pos==n-1) doOp(1,1);
            else { doOp(pos,1); /* retry */ placed--; }
        } else {
            doOp(placed, n-pos);
        }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
